-- lingedge:class=expand
-- +goose Up
CREATE TABLE IF NOT EXISTS tenants (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY) ENGINE=InnoDB;
GRANT SELECT, INSERT, UPDATE, DELETE ON `tenants` TO lingedge_app;
CREATE TABLE IF NOT EXISTS pt (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, created_at DATETIME(3) NOT NULL, tid BIGINT UNSIGNED NULL, PRIMARY KEY (id, created_at), CONSTRAINT fk FOREIGN KEY (tid) REFERENCES tenants(id)) ENGINE=InnoDB PARTITION BY RANGE COLUMNS(created_at) (PARTITION pmax VALUES LESS THAN (MAXVALUE));
GRANT SELECT, INSERT, UPDATE, DELETE ON `pt` TO lingedge_app;
GRANT SELECT, ALTER, DROP ON `pt` TO lingedge_maint;
